#include "gpu_mc.h"
#include <cuda_runtime.h>
#include <curand_kernel.h>
#include <cmath>
#include <algorithm>
#include <limits>

// Constants for the Black-Scholes Monte Carlo pricing
#define MAX_BATCH_SIZE (256 * 1024 * 1024)  // 256 MiB limit
#define BLOCK_SIZE 256

// Custom XORWOW random number generator kernel
__device__ void xorwow_rng(unsigned int* state, unsigned int* output) {
    unsigned int t = state[0] ^ (state[0] >> 2);
    state[0] = state[1];
    state[1] = state[2];
    state[2] = state[3];
    state[3] = state[4];
    state[4] = state[5];
    state[5] = state[5] ^ (state[5] << 4) ^ t ^ (t << 1);
    *output = state[5];
}

// Kernel for Monte Carlo pricing
__global__ void mc_pricing_kernel(
    double S, double K, double r, double q, double sigma, double T,
    unsigned long long nPaths, unsigned long long seed,
    double* prices, double* variances, unsigned int* rng_states) {

    unsigned long long tid = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long stride = gridDim.x * blockDim.x;

    // Initialize RNG state for this thread
    unsigned int rng_state[6];
    rng_state[0] = (unsigned int)(seed + tid * 1103515245 + 12345);
    rng_state[1] = (unsigned int)(seed + tid * 1103515245 + 12346);
    rng_state[2] = (unsigned int)(seed + tid * 1103515245 + 12347);
    rng_state[3] = (unsigned int)(seed + tid * 1103515245 + 12348);
    rng_state[4] = (unsigned int)(seed + tid * 1103515245 + 12349);
    rng_state[5] = (unsigned int)(seed + tid * 1103515245 + 12350);

    // Each thread processes multiple paths if needed
    for (unsigned long long i = tid; i < nPaths; i += stride) {
        // Generate random number using custom RNG
        unsigned int rand_val;
        xorwow_rng(rng_state, &rand_val);

        // Convert to uniform random variable in [0,1)
        double u = rand_val / 4294967296.0;

        // Generate standard normal random variable using Box-Muller transform
        double z = sqrt(-2.0 * log(u)) * cos(2.0 * M_PI * u);

        // Calculate stock price at maturity
        double ST = S * exp((r - q - 0.5 * sigma * sigma) * T + sigma * sqrt(T) * z);

        // Calculate payoff for call option
        double payoff = fmax(ST - K, 0.0);

        // Store result for reduction
        prices[i] = payoff;
    }
}

// Kernel for computing variance and mean
__global__ void compute_stats_kernel(double* prices, double* variances, unsigned long long nPaths, double mean) {
    unsigned long long tid = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long stride = gridDim.x * blockDim.x;

    for (unsigned long long i = tid; i < nPaths; i += stride) {
        double diff = prices[i] - mean;
        variances[i] = diff * diff;
    }
}

McResult gpu_bs_call(double S, double K, double r, double q, double sigma, double T,
                     unsigned long long nPaths, unsigned long long seed, int device) {

    // Set device
    cudaSetDevice(device);

    // Calculate number of blocks needed
    unsigned long long num_blocks = (nPaths + BLOCK_SIZE - 1) / BLOCK_SIZE;
    num_blocks = std::min(num_blocks, (unsigned long long)65535);  // Limit to max blocks

    // Allocate device memory
    double* d_prices = nullptr;
    double* d_variances = nullptr;
    unsigned int* d_rng_states = nullptr;

    // Calculate memory needed (256 MiB limit)
    size_t max_paths = 256 * 1024 * 1024 / sizeof(double);  // 256 MiB limit
    size_t actual_paths = std::min(nPaths, max_paths);

    // Allocate memory for prices and variances
    cudaMalloc(&d_prices, actual_paths * sizeof(double));
    cudaMalloc(&d_variances, actual_paths * sizeof(double));
    cudaMalloc(&d_rng_states, actual_paths * sizeof(unsigned int) * 6);

    // Launch kernel
    mc_pricing_kernel<<<num_blocks, BLOCK_SIZE>>>(
        S, K, r, q, sigma, T, actual_paths, seed, d_prices, d_variances, d_rng_states);

    // Wait for kernel to complete
    cudaDeviceSynchronize();

    // Compute mean and variance
    double* h_prices = new double[actual_paths];
    cudaMemcpy(h_prices, d_prices, actual_paths * sizeof(double), cudaMemcpyDeviceToHost);

    // Calculate mean
    double sum = 0.0;
    for (size_t i = 0; i < actual_paths; i++) {
        sum += h_prices[i];
    }
    double mean = sum / actual_paths;

    // Calculate variance
    double sum_var = 0.0;
    for (size_t i = 0; i < actual_paths; i++) {
        double diff = h_prices[i] - mean;
        sum_var += diff * diff;
    }
    double variance = sum_var / actual_paths;

    // Calculate standard error
    double std_error = sqrt(variance / actual_paths);

    // Calculate final price (discounted)
    double price = mean * exp(-r * T);

    // Cleanup
    delete[] h_prices;
    cudaFree(d_prices);
    cudaFree(d_variances);
    cudaFree(d_rng_states);

    return {price, std_error};
}

